83:function finishGame(){gameOver=true;document.querySelector('#ending-kicker').textContent='THE SHATTERED REACH';document.querySelector('#ending-title').textContent='The song carries on';document.querySelector('#ending-copy').textContent='The Windward Spire wakes. Light runs from ridge to ridge, and the Marches answer.';document.querySelector('#ending-screen').classList.add('visible');document.querySelector('.quest-copy').innerHTML='The Spire is awake. The Marches<br>will remember your song.';document.querySelector('.quest-progress span').textContent='THREAD COMPLETE';showMessage('THE WINDWARD SPIRE AWAKENS')}
84:function interact(){const item=nearestInteractable();if(!item){const mira=npcs.find(n=>Math.hypot(player.x-n.x,player.z-n.z)<4.5);if(mira){mira.talked=true;if(!questAwake){showMessage('Mira: Wake the windstone. The Spire will hear.')}else if(!questSong){questSong=true;showMessage('Mira: Carry this song to the Spire. It will open the way.');document.querySelector('.quest-copy').innerHTML='Mira has shared the old refrain.<br>Carry it to the Windward Spire.';document.querySelector('.quest-progress span').textContent='RETURN TO THE SPIRE'}else showMessage('Mira: Let the song travel.');return}return}const {obj,type}=item;if(type==='windstone'){if(!questAwake){questAwake=true;windstone.material=mats.glow;showMessage('THE WINDSTONE REMEMBERS');document.querySelector('.quest-copy').innerHTML='Mira in the old settlement knows<br>the refrain. Find her nearby.';document.querySelector('.quest-progress span').textContent='SEEK MIRA';player.stamina=Math.min(100,player.stamina+22)}else showMessage('A low hum answers your touch.')}if(type==='spire'){if(!questAwake){showMessage('The heart is silent. Wake the windstone first.');return}if(!questSong){showMessage('The Spire waits for Mira’s song.');return}finishGame()}if(type==='pickup'){obj.active=false;obj.mesh.visible=false;if(obj.type==='amber'){player.stamina=Math.min(100,player.stamina+18);showMessage('AMBER SEED  +18 VIGOR')}else{player.hp=Math.min(player.maxHp,player.hp+1);showMessage('WILD MINT  +1 HEART')}}if(type==='chest'){obj.opened=true;obj.group.rotation.x=-.48;player.durability=Math.min(100,player.durability+12);player.stamina=100;showMessage('RUIN CACHE  •  SABRE RESTORED')}if(type==='prop'){obj.vx+=(player.x-obj.x)*-.55;obj.vz+=(player.z-obj.z)*-.55;showMessage(obj.type==='crate'?'You shove the old crate.':'The boulder shifts with a rumble.')}if(type==='cave'){showMessage('A hidden hollow. Something glimmers within.');player.hp=Math.min(player.maxHp,player.hp+1)}}
85:function jump(){if(gameOver)return;if(player.swimming){player.vy=5;player.grounded=false;return}if(player.grounded&&player.stamina>4){player.vy=8.3;player.grounded=false;player.stamina-=4;player.gliding=false}}
87:function attack(){if(gameOver||player.attack>0||player.durability<=0)return;player.attack=player.weapon==='sabre'?.36:.52;player.durability-=player.weapon==='bow'?.6:1.15;const reach=player.weapon==='spear'?4.4:player.weapon==='bow'?15:3.15;for(const e of enemies){if(e.hp<=0)continue;const dx=e.x-player.x,dz=e.z-player.z,d=Math.hypot(dx,dz);const angle=Math.atan2(dx,dz),delta=Math.atan2(Math.sin(angle-player.yaw),Math.cos(angle-player.yaw));if(d<reach&&Math.abs(delta)<(player.weapon==='bow'?.16:.93)){if(player.weapon==='bow'&&d>5){e.hp-=1;const a=addMesh(new THREE.CylinderGeometry(.035,.035,d,5),mats.gold,player.x,(player.y+1.6+e.group.position.y+1)/2,player.z);a.lookAt(e.x,e.group.position.y+1,e.z);setTimeout(()=>{scene.remove(a);a.geometry.dispose()},180)}else e.hp-=player.weapon==='spear'?2:1;e.stagger=.6;e.state='stagger';const push=Math.max(0,3.8-d)*.27;e.x+=dx/(d||1)*push;e.z+=dz/(d||1)*push;e.group.position.x=e.x;e.group.position.z=e.z;if(e.hp<=0){e.group.visible=false;makePickup(e.x,e.z,'amber');showMessage(e.kind==='sentinel'?'SENTINEL SILENCED':'BRAMBLELING DOWN')}}}if(player.weapon==='bow')showMessage('ARROW LOOSE');}
94:function updatePlayer(dt){if(gameOver)return;const forward=(heldKeys.has('w')||heldKeys.has('arrowup')?-1:0)+(heldKeys.has('s')||heldKeys.has('arrowdown')?1:0)-touchY;const side=(heldKeys.has('d')||heldKeys.has('arrowright')?1:0)-(heldKeys.has('a')||heldKeys.has('arrowleft')?1:0)+touchX;let inputLen=Math.hypot(forward,side);const f=Math.min(1,inputLen);let sprint=heldKeys.has('shift')||sprintTouch;const canSprint=sprint&&player.stamina>2&&inputLen>.1;const swimming=Math.abs(player.x-riverX(player.z))<2.35&&player.z>-155&&player.z<150;player.swimming=swimming;const speed=swimming?2.45:player.gliding?5.8:canSprint?9.6:5.35;if(inputLen>.05){let norm=Math.max(1,inputLen);const fx=-Math.sin(cameraYaw),fz=-Math.cos(cameraYaw),rx=Math.cos(cameraYaw),rz=-Math.sin(cameraYaw);const vx=(fx*forward+rx*side)/norm,vz=(fz*forward+rz*side)/norm;player.x+=vx*speed*dt;player.z+=vz*speed*dt;player.yaw=Math.atan2(vx,vz)}
100:function updateEnemies(dt){if(gameOver)return;for(const e of enemies){if(e.hp<=0)continue;e.cool=Math.max(0,e.cool-dt);e.stagger=Math.max(0,e.stagger-dt);const dx=player.x-e.x,dz=player.z-e.z,d=Math.hypot(dx,dz);if(d<20)e.state='hunt';else if(d>28)e.state='idle';if(e.stagger<=0&&e.state==='hunt'&&d>2.2){const pace=e.kind==='sentinel'?2.15:3.1;e.x+=dx/(d||1)*pace*dt;e.z+=dz/(d||1)*pace*dt;e.group.rotation.y=Math.atan2(dx,dz)}else if(e.stagger<=0&&d<=2.25&&e.cool===0){e.cool=e.kind==='sentinel'?1.65:1.25;e.state='strike';if(player.invuln<=0&&!player.dodge){player.hp=Math.max(0,player.hp-1);player.invuln=.85;drawHearts();showMessage('HIT  −1 HEART');if(player.hp<=0){gameOver=true;document.querySelector('#ending-kicker').textContent='THE WILD MARCHES';document.querySelector('#ending-title').textContent='The trail ends here';document.querySelector('#ending-copy').textContent='The Marches are still waiting. Gather what you learned, and try again.';document.querySelector('#ending-screen').classList.add('visible');showMessage('THE WILD MARCHES WAIT  ·  PRESS R')}}}e.group.position.set(e.x,heightAt(e.x,e.z)+Math.sin(gameTime*4+e.x)*.06,e.z);const bob=e.state==='strike'?Math.sin((e.kind==='sentinel'?1.65:1.25)-e.cool)*.24:Math.sin(gameTime*5+e.z)*.07;e.group.scale.setScalar(e.size*(e.state==='strike'?1.08:1));e.group.position.y+=bob;if(e.state==='strike'&&e.cool>(e.kind==='sentinel'?1.25:.9))e.group.rotation.x=-.25;if(e.cool<.2)e.group.rotation.x=0;}}
108:function updateDiscovery(){for(const mark of landmarks){const d=Math.hypot(player.x-mark.x,player.z-mark.z);if(d<mark.radius&&!mark.found){mark.found=true;if(mark.kind==='stone')continue;discovered=true;document.querySelector('.discovery-name').textContent=mark.name;document.querySelector('#discovery').classList.remove('visible');void document.querySelector('#discovery').offsetWidth;document.querySelector('#discovery').classList.add('visible');document.querySelector('#location-name').textContent=mark.name;const toast=document.querySelector('#location-toast');toast.classList.add('visible');setTimeout(()=>toast.classList.remove('visible'),3500);if(mark.name==='THE WINDWARD SPIRE')document.querySelector('.quest-progress span').textContent=questSong?'RETURN TO THE SPIRE':'SPIRE DISCOVERED'}}}

